    {
      "id": "p3-s2",
      "from": "歸一恩師廟聖子父子主下一切身廣善說正普爲世間不宜",
      "to": "敬禮皈依恩師妙音與聖者父子足，一切深廣善說藏，普為世間不請友",
      "reason": "語音近似（歸一 vs 敬禮，廟 vs 妙音，聖子 vs 聖者，主 vs 足，身廣 vs 深廣，正 vs 藏，不宜 vs 不請友）且與官方課本完全對應",
      "referenceId": "official-p6"
    },
    {
      "id": "p4-s1",
      "from": "喜事三地善道也摩尼法王常照護被與無壓佛會衆典狀罪聖主做師子和無人等",
      "to": "啟示三地善道眼，牟尼法王常照護，遍於無央佛會中，演唱最勝甚深處",
      "reason": "語音近似（喜事 vs 啟示，也 vs 眼，摩尼 vs 牟尼，被與 vs 遍於，無壓 vs 無央，衆 vs 中，典狀 vs 演唱，罪聖主 vs 最勝，做師子 vs 作獅子，無人等 vs 無能等）且與官方課本對應",
      "referenceId": "official-p6"
    },
    {
      "id": "p4-s2",
      "from": "妙異三世恆家世三世諸佛心中時緣起終到第二遍或許榮宋如一世",
      "to": "作獅子吼無能等，妙音恩師恆加持，三世諸佛心中心，緣起中道離二邊",
      "reason": "語音近似（妙異 vs 作獅子吼，恆家世 vs 恆加持，心中時 vs 心中心，終到 vs 中道，第二遍 vs 離二邊）且與官方課本對應",
      "referenceId": "official-p6"
    },
    {
      "id": "p5-s1",
      "from": "自心心裏還奢受由天教授登高位一致所見世衆生也說善道者自在",
      "to": "佛記龍猛如理釋，至心敬禮哀攝受，由前教授登高位，以自所見示眾生",
      "reason": "語音近似（自心心裏還奢受 vs 佛記龍猛如理釋，由天 vs 由前，一致 vs 以自，世衆生 vs 示眾生）且與官方課本對應",
      "referenceId": "official-p6"
    },
    {
      "id": "p5-s2",
      "from": "敬禮吉祥聖殿主或許致尊妙應家開寫同盟究竟地正德西地使命位",
      "to": "演說善道得自在，敬禮吉祥聖天足，奉行至尊妙音教，開顯龍猛究竟意",
      "reason": "語音近似（敬禮吉祥聖殿主 vs 演說善道得自在，致尊 vs 至尊，妙應家 vs 妙音教，開寫同盟 vs 開顯龍猛）且與官方課本對應",
      "referenceId": "official-p6"
    },
    {
      "id": "p6-s1",
      "from": "同面敬禮佛無諸惟悉難色大仙道容孟不共諸幻藥圓滿開險月城時",
      "to": "證得悉地持明位，頭面敬禮佛護足，微細難測大仙道，龍猛不共諸關要",
      "reason": "語音近似（同面 vs 頭面，佛無諸 vs 佛護足，容孟 vs 龍猛，幻藥 vs 諸關要，開險月城時 vs 圓滿開顯月稱師）且與官方課本對應",
      "referenceId": "official-p6"
    },
    {
      "id": "p6-s2",
      "from": "其今天主我敬禮當往其我所沉重三百大色光解釋我已不夠敬慧也",
      "to": "圓滿開顯月稱師，及靜天足我敬禮，龍猛提婆所成宗，三派大車廣解釋",
      "reason": "語音近似（其今天主 vs 圓滿開顯月稱師，沉重三百 vs 龍猛提婆，大色光 vs 大車）且與官方課本對應",
      "referenceId": "official-p6"
    },
    {
      "id": "p7-s1",
      "from": "不共妙異皆善見此間欲選以終者我爲主習惡說夠因衆情故已盡語",
      "to": "無垢淨慧眼，此間欲宣彼宗者，我為除其惡說垢，因眾請故以淨語",
      "reason": "語音近似（不共妙異 vs 無垢淨慧眼，欲選以終者 vs 欲宣彼宗者，主習 vs 為除，夠 vs 垢，衆情 vs 眾請）且與官方課本對應",
      "referenceId": "official-p6"
    },
    {
      "id": "p8-s1",
      "from": "當其往事如終問這是",
      "to": "當即廣釋入中論",
      "reason": "語音近似（當其 vs 當即，往事 vs 廣釋，如終問 vs 入中論）且與官方課本對應",
      "referenceId": "official-p6"
